mapper.sql:
WHERE 1 = 1

    AND t.status = #{query.status}


    AND t.task_type = #{query.taskType}


    AND c.case_no = #{query.caseNo}


    AND (
        t.task_no LIKE CONCAT('%', #{query.keyword}, '%')
        OR c.case_no LIKE CONCAT('%', #{query.keyword}, '%')
    )

mapper.select:
SELECT COUNT(*)
FROM analysis_task
WHERE image_file_id = #{imageFileId}
  AND task_type = #{taskType}
  AND status IN ('CREATED', 'WAITING', 'RUNNING', 'RETRYING')

mapper.update:
UPDATE analysis_task
SET status = 'RETRYING',
    retry_count = retry_count + 1,
    started_at = NULL,
    finished_at = NULL,
    updated_at = #{updatedAt}
WHERE id = #{taskId}
  AND status = 'FAILED'
  AND retry_count = #{expectedRetryCount}
  AND retry_count < max_retry_count
